<script setup>
import { onBeforeUnmount, ref, watch } from "vue"; import { useRoute, useRouter } from "vue-router";
import AppHeader from "../components/AppHeader.vue"; import BottomNav from "../components/BottomNav.vue"; import StoryCard from "../components/StoryCard.vue"; import { fetchNovelList } from "../lib/api.js"; import { normalizedQuery } from "../lib/content.js";
const route=useRoute(),router=useRouter(),query=ref(String(route.query.q||"")),items=ref([]),loading=ref(false),searched=ref(false),error=ref(""); let timer;
async function search(){const q=normalizedQuery(query.value); if(!q){items.value=[];searched.value=false;error.value="";router.replace({query:{}});return;} loading.value=true;error.value="";router.replace({query:{q}});try{items.value=(await fetchNovelList(route.params.code,{q,page:1,pageSize:30})).items;searched.value=true;}catch(e){error.value=e.message;}finally{loading.value=false;}}
watch(query,()=>{clearTimeout(timer);timer=setTimeout(search,350);}); if(normalizedQuery(query.value)) search(); onBeforeUnmount(()=>clearTimeout(timer));
</script>
<template><div class="page with-nav"><header class="search-header"><AppHeader back /><label class="search-box"><i class="fa-solid fa-magnifying-glass" /><input v-model="query" autofocus type="search" placeholder="Search stories" aria-label="Search stories" /><button v-if="query" aria-label="Clear search" @click="query=''">×</button></label></header><section class="search-content"><div v-if="loading" class="state-block compact-state"><i class="fa-solid fa-spinner fa-spin" /><p>Searching…</p></div><div v-else-if="error" class="state-block compact-state"><p class="error-text">{{ error }}</p><button class="secondary-button" @click="search">Try again</button></div><div v-else-if="items.length" class="story-grid"><StoryCard v-for="story in items" :key="story.id" :story="story" /></div><div v-else-if="searched" class="state-block"><i class="fa-regular fa-face-meh" /><p>No stories match “{{ normalizedQuery(query) }}”.</p></div><div v-else class="search-hint"><i class="fa-solid fa-feather-pointed" /><p>Find your next story by title, author, or category.</p></div></section><BottomNav /></div></template>
